//8003A1B8
Entity* SpawnEntity(Entity* entity, int initData, int checkSpawnZone)

{
    EntityRecord* initType;
    AnimationData* animData;
    Entity* entity_00;
    Entity* spawnedEntity;
    uint spriteTableIndex;
    int paletteIndex;
    int sheetSize;
    byte flags;

    initType = CheckInitData(initData);
    if (initType == (EntityRecord*)0x0) {
        spawnedEntity = (Entity*)0x0;
        return spawnedEntity;
    }
    if (checkSpawnZone == 0) {
        if (g_player.tileX < (int)(uint)initType->xMin) {
            spawnedEntity = (Entity*)0x0;
            return spawnedEntity;
        }
        if ((int)(uint)initType->xMax < g_player.tileX) {
            spawnedEntity = (Entity*)0x0;
            return spawnedEntity;
        }
        if (g_player.tileY < (int)(uint)initType->yMin) {
            spawnedEntity = (Entity*)0x0;
            return spawnedEntity;
        }
        if ((int)(uint)initType->yMax < g_player.tileY) {
            spawnedEntity = (Entity*)0x0;
            return spawnedEntity;
        }
    }
    flags = initType->spriteDirection;
    if (((flags & 0x40) != 0) || (spawnedEntity = (Entity*)0x0, checkSpawnZone != 0)) {
        animData = (AnimationData*)
            GetEntityDataId(flags & 0x80, (uint)initType->spriteTableIndex, &paletteIndex,
                &sheetSize);
        spawnedEntity = (Entity*)0x0;
        if (animData != (AnimationData*)0x0) {
            entity_00 = AllocateEntitySlot();
            spawnedEntity = (Entity*)0x0;
            if (entity_00 != (Entity*)0x0) {
                spriteTableIndex = (uint)initType->spriteTableIndex;
                if ((flags & 0x80) != 0) {
                    spriteTableIndex = spriteTableIndex + 0x100;
                }
                InitEntity(entity_00, entity, animData, (int)initType, spriteTableIndex, initData,
                    ((uint)initType->xPox * 0xc + 0xc) * 0x10000,
                    ((uint)initType->yPos * 8 + 8) * 0x10000, (uint)initType->height << 0x13, 0,
                    (uint)(&g_warpZones)[flags & 3], paletteIndex, sheetSize);
                spawnedEntity = entity_00;
            }
        }
    }
    return spawnedEntity;
}

